-- 1차 캐시가 삼킨다

@Test
@Transactional
void 캐시가_삼킨다() {
    Member m = memberRepository.save(new Member("김"));
    em.flush();
    System.out.println("--- findById 시작 ---");
    memberRepository.findById(m.getId());
    System.out.println("--- findById 끝 ---");
}

Hibernate: insert into member (username, id) values (?, ?)
--- findById 시작 ---
--- findById 끝 ---

--   select 가 없다
