@Test
@Transactional
void 배치() {
    long n = counter.count(() -> {
        for (int i = 0; i < 10; i++) {
            memberRepository.save(new Member("m" + i));
        }
        em.flush();
    });
    System.out.println("실제 왕복: " + n);
}

