-- @GeneratedValue 가 배치를 막는다

@Id @GeneratedValue(strategy = GenerationType.IDENTITY)
private Long id;

@Test
void identity_배치() {
    long n = counter.count(() -> {
        for (int i = 0; i < 10; i++)
            memberRepository.save(new Member("m" + i));
        em.flush();
    });
    System.out.println("실제 왕복: " + n);
}

실제 왕복: 10

--   IDENTITY 는 즉시 insert 해야 id 를 안다
--   그래서 배치가 안 된다
--   ① 에서 본 그것이다


